        if (ownerDto == null) {
            return null;
        }
        String line1 = ownerDto.getAddressLine1();
        if (line1 != null && !line1.trim().isEmpty()) {
            String composed = AddressNormalizer.normalize(line1);
            String line2 = ownerDto.getAddressLine2();
